import os,re
d=os.path.normpath(os.environ['RLM_SESSION_DIR'])
t=open(d+'/../../sessions/'+os.path.basename(d)+'.jsonl').read()
def parse(name):
    m=re.search(re.escape(name)+r' \((\d+)x(\d+)\):\n',t)
    h,w=int(m[1]),int(m[2])
    return [[int(x) for x in r.split()] for r in t[m.end():].split('\n')[:h]]
I=parse('Demo pair 1 input'); O=parse('Demo pair 1 output')
