for r,(a,b) in enumerate(zip(I,O)):
    for c,(x,y) in enumerate(zip(a,b)):
        if x!=y: print(r,c,x,'->',y)

def transform(g):
    import numpy as np
    a=np.array(g); out=a.copy(); H,W=a.shape
    seen=np.zeros_like(a,bool); boxes=[]
    for r in range(H):
        for c in range(W):
            if a[r,c]==3 and not seen[r,c]:
                st=[(r,c)]; seen[r,c]=True; comp=[]
                while st:
                    y,x=st.pop(); comp.append((y,x))
                    for dy,dx in((1,0),(-1,0),(0,1),(0,-1)):
                        ny,nx=y+dy,x+dx
                        if 0<=ny<H and 0<=nx<W and a[ny,nx]==3 and not seen[ny,nx]:
                            seen[ny,nx]=True; st.append((ny,nx))
                ys=[p[0] for p in comp]; xs=[p[1] for p in comp]
                boxes.append((min(ys),max(ys),min(xs),max(xs)))
    for r in range(H):
        for c in range(W):
            if a[r,c]==2 and any(r0<=r<=r1 and c0<=c<=c1 for r0,r1,c0,c1 in boxes):
                for dy in(-1,0,1):
                    for dx in(-1,0,1):
                        ny,nx=r+dy,c+dx
                        if 0<=ny<H and 0<=nx<W and a[ny,nx]!=2:
                            out[ny,nx]=1
    return out.tolist()
print(transform(I)==O)

